5|namespace Laundry.Desktop.ViewModels;
6|
7|/// <summary>
8|/// Layar masuk, daftar, dan lupa sandi. Semuanya memakai jalur API yang sama dengan pengguna lain —
9|/// tidak ada akun lokal. Nomor telepon disimpan sebagai teks biasa karena itulah identitasnya di PRD.
10|/// </summary>
11|public partial class LoginViewModel : ObservableObject
12|{
13|    private const string ModeMasuk = "Masuk";
14|    private const string ModeDaftar = "Daftar";
15|    private const string ModeLupa = "Lupa";
16|
17|    [ObservableProperty] private string _nomor = "";
18|    [ObservableProperty] private string _nama = "";
19|    [ObservableProperty] private string _kodeOtp = "";
20|    [ObservableProperty] private string _mode = ModeMasuk;
21|    [ObservableProperty] private string? _galat;
22|    [ObservableProperty] private string? _info;
23|    [ObservableProperty] private string? _pesanUmum;
24|    [ObservableProperty] private string? _kodeDev;
25|        [ObservableProperty] private bool _sibuk;
26|
27|        [ObservableProperty] private bool _sandiTersembunyi = true;
28|        [ObservableProperty] private bool _sandiBaruTersembunyi = true;
29|        [ObservableProperty] private bool _sandiResetTersembunyi = true;
30|
31|        public string Sandi { get; set; } = "";
32|
33|    public string SandiBaru { get; set; } = "";
34|
35|    public bool LagiMasuk => Mode == ModeMasuk;
36|
37|    public bool LagiDaftar => Mode == ModeDaftar;
38|
39|    public bool LagiLupa => Mode == ModeLupa;
40|
41|    public bool PunyaTantangan => TantanganId.HasValue;
42|
43|    private Guid? TantanganId { get; set; }
44|
45|    partial void OnModeChanged(string value)
46|    {
47|        OnPropertyChanged(nameof(LagiMasuk));
48|        OnPropertyChanged(nameof(LagiDaftar));
49|        OnPropertyChanged(nameof(LagiLupa));
50|    }
51|
52|    [RelayCommand]
53|    private void PilihMode(string pilihan)
54|    {
55|        Mode = pilihan;
56|        Galat = null;
57|        Info = null;
58|        KodeDev = null;
59|    }
60|
61|    [RelayCommand]
62|    private async Task MasukAsync()
63|    {
64|        if (string.IsNullOrWhiteSpace(Nomor) || string.IsNullOrEmpty(Sandi))
65|        {
66|            Galat = "Isi nomor dan kata sandi.";
67|            return;
68|        }
69|
70|        await JalankanAsync(async () =>
71|        {
72|            var tokens = await App.Instance.Api.KirimAsync<TokenResponse>("api/auth/login",
73|                new { phone = Nomor.Trim(), password = Sandi });
74|            await SelesaiMasukAsync(tokens, Nomor.Trim());
75|        });
76|    }
77|
78|    [RelayCommand]
79|    private async Task DaftarMulaiAsync()
80|    {
81|        if (string.IsNullOrWhiteSpace(Nomor))
82|        {
83|            Galat = "Isi nomor telepon dulu.";
84|            return;
85|        }
86|
87|        await JalankanAsync(async () =>
88|        {
89|            var hasil = await App.Instance.Api.KirimAsync<KodeHasil>("api/auth/register/start",
90|                new { phone = Nomor.Trim() });
91|            TantanganId = hasil?.ChallengeId;
92|            KodeDev = hasil?.DevCode;
93|            Info = hasil?.DevCode is null
94|                ? "Kode verifikasi dikirim ke nomor ini."
95|                : "Lingkungan pengembangan: kode muncul di layar, tidak dikirim lewat WhatsApp.";
96|            OnPropertyChanged(nameof(PunyaTantangan));
97|        });
98|    }
99|
100|    [RelayCommand]
101|    private async Task DaftarSelesaiAsync()
102|    {
103|        if (TantanganId is null || string.IsNullOrWhiteSpace(KodeOtp) || string.IsNullOrEmpty(SandiBaru) ||
104|            string.IsNullOrWhiteSpace(Nama))
105|        {
106|            Galat = "Lengkapi kode, nama, dan kata sandi baru.";
107|            return;
108|        }
109|
110|        await JalankanAsync(async () =>
111|        {
112|            var tokens = await App.Instance.Api.KirimAsync<TokenResponse>("api/auth/register/complete",
113|                new { challengeId = TantanganId, otp = KodeOtp.Trim(), password = SandiBaru, nama = Nama.Trim() });
114|            await SelesaiMasukAsync(tokens, Nomor.Trim());
115|        });
116|    }
117|
118|    [RelayCommand]
119|    private async Task LupaMulaiAsync()
120|    {
121|        if (string.IsNullOrWhiteSpace(Nomor))
122|        {
123|            Galat = "Isi nomor telepon akun kamu.";
124|            return;
125|        }
126|
127|        await JalankanAsync(async () =>
128|        {
129|            var hasil = await App.Instance.Api.KirimAsync<ResetMulaiHasil>("api/auth/reset/start",
130|                new { phone = Nomor.Trim() });
131|            TantanganId = hasil?.ChallengeId;
132|            KodeDev = hasil?.DevCode;
133|            Info = hasil?.Sent == true
134|                ? "Kode reset dikirim. Masukkan kode dan kata sandi baru di bawah."
135|                : hasil?.Message ?? "Nomor itu belum terdaftar.";
136|            OnPropertyChanged(nameof(PunyaTantangan));
137|        });
138|    }
139|
140|    [RelayCommand]
141|    private async Task LupaSelesaiAsync()
142|    {
143|        if (TantanganId is null || string.IsNullOrWhiteSpace(KodeOtp) || string.IsNullOrEmpty(SandiBaru))
144|        {
145|            Galat = "Lengkapi kode dan kata sandi baru.";
146|            return;
147|        }
148|
149|        await JalankanAsync(async () =>
150|        {
151|            var hasil = await App.Instance.Api.KirimAsync<PesanHasil>("api/auth/reset/complete",
152|                new { challengeId = TantanganId, otp = KodeOtp.Trim(), newPassword = SandiBaru });
153|            Mode = ModeMasuk;
154|            Info = hasil?.Message ?? "Kata sandi diganti. Silakan masuk.";
155|        });
156|    }
157|
158|    private async Task SelesaiMasukAsync(TokenResponse? tokens, string nomor)
159|    {
160|        if (tokens is null)
161|        {
162|            Galat = "Server tidak mengirim token.";
163|            return;
164|        }
165|
166|        App.Instance.Api.SimpanToken(tokens.AccessToken, tokens.RefreshToken);
167|        var saya = await App.Instance.Api.AmbilAsync<ProfilHasil>("api/auth/me");
168|        if (saya is null)
169|        {
170|            Galat = "Identitas tidak dapat dibaca dari server.";
171|            return;
172|        }
173|
174|        var sesi = App.Instance.Sesi;
175|        sesi.Isi(tokens, nama: null, peran: saya.Role, nomor: nomor);
176|        App.Instance.Preferensi.NomorTerakhir = nomor;
177|        App.Instance.Preferensi.Simpan();
178|        App.Instance.BukaUtama();
179|    }
180|
181|    private async Task JalankanAsync(Func<Task> aksi)
182|    {
183|        if (Sibuk) return;
184|        Sibuk = true;
185|        Galat = null;
186|        try
187|        {
188|            await aksi();
189|        }
190|        catch (ApiException ex)
191|        {
192|            Galat = ex.Message;
193|        }
194|        catch (Exception ex)
195|        {
196|            Galat = ex.Message;
197|        }
198|        finally
199|        {
200|            Sibuk = false;
201|            OnPropertyChanged(nameof(PunyaTantangan));
202|        }
203|    }
